(function(){
  var debug=location.search.includes('debug-consent=1');
  var isEU=debug?true:(window.__isEU===true);
  if(debug){console.log('[cookie] debug mode');localStorage.removeItem('cookie_consent');}

  function getConsent(){
    try{
      var raw=localStorage.getItem('cookie_consent');
      if(!raw) return null;
      var d=JSON.parse(raw);
      if(typeof d==='string') return d;
      var m=1000*60*60*24*180;
      if(Date.now()-d.ts>m){localStorage.removeItem('cookie_consent');return null;}
      return d.value;
    }catch(e){return null;}
  }

  function setConsent(v){
    localStorage.setItem('cookie_consent',JSON.stringify({value:v,ts:Date.now()}));
  }

  function grant(){
    gtag('consent','update',{ad_storage:'granted',analytics_storage:'granted',ad_user_data:'granted',ad_personalization:'granted'});
  }

  function deny(){
    gtag('consent','update',{ad_storage:'denied',analytics_storage:'denied',ad_user_data:'denied',ad_personalization:'denied'});
  }

  var saved=getConsent();
  if(!isEU){grant();if(window.__ads_loadAds)window.__ads_loadAds();return;}
  if(saved==='accepted'){grant();if(window.__ads_loadAds)window.__ads_loadAds();return;}
  if(saved==='rejected'){deny();return;}

  // 创建 modal
  var overlay=document.createElement('div');
  overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9999;display:flex;align-items:center;justify-content:center;';
  var modal=document.createElement('div');
  modal.style.cssText='background:#fff;width:520px;max-width:92%;border-radius:16px;padding:22px 24px;box-shadow:0 20px 60px rgba(0,0,0,.25);font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif;';
  modal.innerHTML="<div style='font-size:18px;font-weight:700;margin-bottom:10px;'>🍪 We respect your privacy</div><div style='font-size:13px;color:#444;line-height:1.7;'>We use cookies and JavaScript to make this website work properly, remember your preferences, and improve your experience.</div><div style='font-size:13px;color:#444;line-height:1.7;margin-top:8px;'>We may also use them to understand how the site is used and keep our content free.</div><div style='font-size:12px;color:#666;margin-top:10px;'>We do not collect sensitive personal data. Learn more in our <a href='https://docs.w3cub.com/privacy-policy' target='_blank' style='color:#2563eb;text-decoration:underline;'>Privacy Policy</a>.</div><div style='margin-top:18px;display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap;'><button id='cookie-reject' style='padding:8px 14px;border:none;border-radius:8px;background:#eee;color:#555;cursor:pointer;'>Decline</button><button id='cookie-accept' style='padding:8px 16px;border:none;border-radius:8px;background:#2563eb;color:#fff;font-weight:600;cursor:pointer;'>Accept All</button></div>";
  overlay.appendChild(modal);
  document.body.appendChild(overlay);

  var acceptBtn=modal.querySelector('#cookie-accept');
  var rejectBtn=modal.querySelector('#cookie-reject');

  acceptBtn.onclick=function(){
    setConsent('accepted');
    grant();
    overlay.remove();
    if(window.__ads_loadAds)window.__ads_loadAds(); // 点击同意后加载广告
  };
  rejectBtn.onclick=function(){
    setConsent('rejected');
    deny();
    overlay.remove();
  };
})();

(function(){
  if(window.__ads_loader_init) return;
  window.__ads_loader_init = true;

  function getConsent(){
    try{
      var raw=localStorage.getItem('cookie_consent');
      if(!raw) return null;
      var d=JSON.parse(raw);
      if(typeof d==='string') return d;
      var m=1000*60*60*24*180;
      if(Date.now()-d.ts>m){localStorage.removeItem('cookie_consent');return null;}
      return d.value;
    }catch(e){return null;}
  }

  function loadAds(){
    if(window.__ads_loaded) return;
    window.__ads_loaded = true;

    // 常规 Adsense
    var s=document.createElement('script');
    s.src='https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-2572770204602497';
    s.async=true;
    s.crossOrigin='anonymous';
    document.head.appendChild(s);

    // AMP Auto Ads
    var amp=document.createElement('script');
    amp.async=true;
    amp.setAttribute('custom-element','amp-auto-ads');
    amp.src='https://cdn.ampproject.org/v0/amp-auto-ads-0.1.js';
    document.head.appendChild(amp);

    // 插入 <amp-auto-ads>
    if(document.body && !document.querySelector('amp-auto-ads')){
      var autoAds=document.createElement('amp-auto-ads');
      autoAds.setAttribute('type','adsense');
      autoAds.setAttribute('data-ad-client','ca-pub-2572770204602497');
      document.body.appendChild(autoAds);
    }
  }

  // 暴露给全局，cookie-modal 同意后调用
  window.__ads_loadAds = loadAds;

  var isEU=window.__isEU===true;
  var saved=getConsent();

  if(!isEU) loadAds();
  else if(saved==='accepted') loadAds();
})();
